package com.mvt.backApp.user.service;
import com.mvt.backApp.agent.dto.*;import com.mvt.backApp.agent.entity.*;import com.mvt.backApp.agent.repository.CarePartnerProfileRepository;import com.mvt.backApp.common.dto.*;import com.mvt.backApp.common.exception.ApiException;import com.mvt.backApp.common.id.*;import com.mvt.backApp.common.security.RoleNames;import com.mvt.backApp.common.service.FileStorageService;import com.mvt.backApp.patient.dto.*;import com.mvt.backApp.patient.entity.PatientProfile;import com.mvt.backApp.patient.repository.PatientProfileRepository;import com.mvt.backApp.security.model.AuthenticatedUser;import com.mvt.backApp.security.service.JwtService;import com.mvt.backApp.user.entity.*;import com.mvt.backApp.user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.time.LocalDateTime;import java.util.*;
@Service @RequiredArgsConstructor public class AuthService{
 private final FileStorageService fileStorageService;private final PasswordEncoder passwordEncoder;private final RoleRepository roleRepository;private final UserRepository userRepository;private final CarePartnerProfileRepository partnerRepository;private final PatientProfileRepository patientRepository;private final AuthenticationManager authenticationManager;private final JwtService jwtService;private final EmailOtpService emailOtpService;private final BusinessIdService businessIdService;
 @Transactional public PatientRegistrationResponseDto registerPatient(PatientRegistrationDto r){return createPatient(r,null);}
 @Transactional public PatientRegistrationResponseDto registerPatientForCurrentPartner(PatientRegistrationDto r){return createPatient(r,currentApprovedPartner());}
 private PatientRegistrationResponseDto createPatient(PatientRegistrationDto r,CarePartnerProfile ref){validateRegistration(r.getPassword(),r.getConfirmPassword(),r.isWhatsappSameAsMobile(),r.getWhatsappNumber());String email=normalize(r.getEmail());duplicate(email);emailOtpService.verifyAndConsume(email,OtpPurpose.PATIENT_REGISTRATION,r.getEmailOtp());User u=buildUser(email,r.getPassword(),r.getFirstName(),r.getLastName(),r.getGender(),role(RoleNames.PATIENT,"PATIENT_ROLE_MISSING","error.system.patientRoleMissing"));u=userRepository.save(u);PatientProfile p=new PatientProfile();p.setUser(u);p.setPatientId(businessIdService.next(BusinessIdKind.PATIENT,r.getCountryCode()));p.setCountryCode(r.getCountryCode().trim().toUpperCase(Locale.ROOT));p.setMobileNumber(r.getMobileNumber());p.setWhatsappSameAsMobile(r.isWhatsappSameAsMobile());p.setWhatsappNumber(r.isWhatsappSameAsMobile()?r.getMobileNumber():r.getWhatsappNumber());p.setReferredBy(ref);p.setReferredAt(ref==null?null:LocalDateTime.now());patientRepository.save(p);return PatientRegistrationResponseDto.builder().patientId(p.getPatientId()).email(email).referredByPartnerId(ref==null?null:ref.getPartnerId()).build();}
 @Transactional public CarePartnerRegistrationResponseDto registerCarePartner(CarePartnerRegistrationDto r){validateRegistration(r.getPassword(),r.getConfirmPassword(),r.isWhatsappSameAsMobile(),r.getWhatsappNumber());document(r.getVerificationDocument());String email=normalize(r.getEmail());duplicate(email);emailOtpService.verifyAndConsume(email,OtpPurpose.CARE_PARTNER_REGISTRATION,r.getEmailOtp());String url=store(r.getVerificationDocument());User u=buildUser(email,r.getPassword(),r.getFirstName(),r.getLastName(),r.getGender(),role(RoleNames.CARE_PARTNER,"CARE_PARTNER_ROLE_MISSING","error.system.carePartnerRoleMissing"));u=userRepository.save(u);CarePartnerProfile p=new CarePartnerProfile();p.setUser(u);p.setPartnerId(businessIdService.next(BusinessIdKind.AGENT,r.getCountryCode()));p.setCompanyName(r.getCompanyName().trim());p.setCountryCode(r.getCountryCode().trim().toUpperCase(Locale.ROOT));p.setMobileNumber(r.getMobileNumber());p.setWhatsappSameAsMobile(r.isWhatsappSameAsMobile());p.setWhatsappNumber(r.isWhatsappSameAsMobile()?r.getMobileNumber():r.getWhatsappNumber());p.setDocumentType(r.getDocumentType());p.setDocumentNumber(r.getDocumentNumber().trim());p.setVerificationDocumentUrl(url);p.setApprovalStatus(ApprovalStatus.PENDING);partnerRepository.save(p);return CarePartnerRegistrationResponseDto.builder().partnerId(p.getPartnerId()).email(email).approvalStatus(p.getApprovalStatus()).build();}
 @Transactional(readOnly=true)public JwtResponseDto login(LoginRequestDto r){String e=normalize(r.getEmail());var a=authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(e,r.getPassword()));AuthenticatedUser p=(AuthenticatedUser)a.getPrincipal();User u=userRepository.findByEmail(p.getEmail()).orElseThrow(()->new ApiException("INVALID_CREDENTIALS","error.auth.invalidCredentials",401));enforce(u);return JwtResponseDto.builder().token(jwtService.generateToken(p)).userId(p.getUserId()).email(p.getEmail()).role(p.getRole()).permissions(p.getAuthorities().stream().map(x->x.getAuthority()).sorted().toList()).build();}
 private User buildUser(String e,String raw,String f,String l,Gender g,Role r){User u=new User();u.setEmail(e);u.setPasswordHash(passwordEncoder.encode(raw));u.setFirstName(f.trim());u.setLastName(l.trim());u.setGender(g);u.setRole(r);u.setEmailVerified(true);u.setMustChangePassword(false);u.setActive(true);u.setDeleted(false);return u;}
 private void validateRegistration(String p,String c,boolean same,String w){if(!Objects.equals(p,c))throw new ApiException("PASSWORDS_DO_NOT_MATCH","validation.confirmPassword.mismatch",400);if(!same&&(w==null||w.isBlank()))throw new ApiException("WHATSAPP_REQUIRED","validation.whatsapp.required",400);}private void duplicate(String e){if(userRepository.existsByEmailIgnoreCase(e))throw new ApiException("DUPLICATE_EMAIL","error.registration.emailExists",409);}private Role role(String n,String code,String key){return roleRepository.findByName(n).orElseThrow(()->new ApiException(code,key,500));}
 private void document(MultipartFile f){if(f==null||f.isEmpty())throw new ApiException("VERIFICATION_DOCUMENT_REQUIRED","validation.verificationDocument.required",400);if(f.getSize()>10L*1024*1024)throw new ApiException("DOCUMENT_TOO_LARGE","error.registration.documentSize",413);if(!Set.of("application/pdf","image/jpeg").contains(f.getContentType()))throw new ApiException("INVALID_DOCUMENT_TYPE","error.registration.documentType",400);}private String store(MultipartFile f){String ext="application/pdf".equals(f.getContentType())?".pdf":".jpg";try{return fileStorageService.uploadFile(f,"AGT-DOC-"+UUID.randomUUID()+ext);}catch(IOException x){throw new ApiException("DOCUMENT_UPLOAD_FAILED","error.registration.documentUpload",500);}}
 private CarePartnerProfile currentApprovedPartner(){Object x=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(x instanceof AuthenticatedUser a))throw new ApiException("AUTHENTICATION_REQUIRED","error.authentication.required",401);User u=userRepository.findById(a.getUserId()).orElseThrow(()->new ApiException("AUTHENTICATED_USER_NOT_FOUND","error.authentication.required",401));CarePartnerProfile p=partnerRepository.findByUser(u).orElseThrow(()->new ApiException("CARE_PARTNER_PROFILE_MISSING","error.auth.carePartnerProfileMissing",403));if(p.getApprovalStatus()!=ApprovalStatus.APPROVED)throw new ApiException("CARE_PARTNER_NOT_APPROVED","error.auth.carePartnerPending",403);return p;}private void enforce(User u){if(u.getRole()==null||!RoleNames.CARE_PARTNER.equals(u.getRole().getName()))return;CarePartnerProfile p=partnerRepository.findByUser(u).orElseThrow(()->new ApiException("CARE_PARTNER_PROFILE_MISSING","error.auth.carePartnerProfileMissing",403));if(p.getApprovalStatus()!=ApprovalStatus.APPROVED)throw new ApiException(p.getApprovalStatus()==ApprovalStatus.REJECTED?"CARE_PARTNER_REJECTED":"CARE_PARTNER_PENDING",p.getApprovalStatus()==ApprovalStatus.REJECTED?"error.auth.carePartnerRejected":"error.auth.carePartnerPending",403);}private String normalize(String e){return e.trim().toLowerCase(Locale.ROOT);}}
